#!/usr/bin/env python3
from __future__ import annotations

import base64
import gzip
from pathlib import Path

APP_STATE_GZIP_BASE64 = """"""


def replace_once(path: str, old: str, new: str) -> None:
    file = Path(path)
    text = file.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"Expected one match in {path}, found {count}: {old[:120]!r}")
    file.write_text(text.replace(old, new, 1), encoding="utf-8")


Path("Sources/AgenTM5N/App/AppState.swift").write_bytes(
    gzip.decompress(base64.b64decode(APP_STATE_GZIP_BASE64))
)

models = "Sources/AgenTM5N/Domain/Models.swift"
replace_once(
    models,
    '  case neuralEngine = "Neural Engine"\n  case settings = "Settings"',
    '  case neuralEngine = "Neural Engine"\n  case memory = "Workspace Memory"\n  case settings = "Settings"',
)
replace_once(
    models,
    '    case .neuralEngine: "brain.head.profile"\n    case .settings: "gearshape"',
    '    case .neuralEngine: "brain.head.profile"\n    case .memory: "books.vertical"\n    case .settings: "gearshape"',
)

root = "Sources/AgenTM5N/Views/RootView.swift"
replace_once(
    root,
    '        case .neuralEngine:\n          NeuralEngineView()\n        case .settings:',
    '        case .neuralEngine:\n          NeuralEngineView()\n        case .memory:\n          WorkspaceMemoryView()\n        case .settings:',
)
replace_once(
    root,
    '    case .neuralEngine:\n      return "Neural Engine"\n    case .settings:',
    '''    case .neuralEngine:
      return "Neural Engine"
    case .memory:
      return L10n.text(
        de: "Workspace-Gedächtnis",
        en: "Workspace Memory",
        fr: "Mémoire de l’espace de travail"
      )
    case .settings:''',
)

build = "scripts/build-app.sh"
replace_once(build, 'VERSION="0.3.2"', 'VERSION="0.4.0"')
replace_once(build, 'BUILD_NUMBER="11"', 'BUILD_NUMBER="12"')

roadmap = "docs/ROADMAP.md"
replace_once(
    roadmap,
    '''## Milestone 3: local intelligence

- Core ML embeddings
- semantic workspace index
- context ranking and deduplication
- prompt compression
- semantic response cache
- local secret and command-risk classification''',
    '''## Milestone 3: local intelligence

### In development for 0.4.0

- isolated Core ML text embedding batches
- persistent semantic workspace index
- safe UTF-8 workspace scanning and bounded chunking
- semantic search with relative paths and line ranges
- agent tools for index status, build, search and clear
- dedicated Workspace Memory user interface

### Planned next

- automatic context ranking and deduplication
- prompt compression
- semantic response cache
- local secret and command-risk classification''',
)
